// Runtime for the lifted VS2013 CRT libm (src/dotnet/vs2013_libm_gen.cpp, generated by tools/libm/gen_lift.py from the
// x64 machine code of msvcr120_clr0400.dll). The generated code is a statement-by-statement translation of the CRT's own
// x86-64 instructions (SSE2, VEX scalar, FMA3, 64-bit integer ops) into C++ over an emulated register file, flags and
// stack, so it reproduces the CRT's results bit for bit on any host. Private project: never distributed.
#pragma once

#include <bit>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#ifdef _MSC_VER
#include <intrin.h>
#endif

namespace ksp::dotnet::vs2013::lift {

struct X128 {
    uint64_t lo, hi;
};

enum Gpr { RAX, RCX, RDX, RBX, RSP, RBP, RSI, RDI, R8, R9, R10, R11, R12, R13, R14, R15 };

constexpr uint64_t kStackBase = 0x00007FF000000000ull;
constexpr uint64_t kStackSize = 4096;
constexpr uint64_t kScratchOff = kStackSize - 64;  // 64 bytes at the top of the stack block: fake errno cell etc.

struct Seg {
    uint64_t base;
    uint64_t size;
    const uint8_t* data;
};
// One lifted library (msvcr120, ucrtbase) = its read-only data segments + the VA of its "FMA3 usable" dword. The flag
// is initialised by the CRT at start-up (_set_FMA3_enable); a read of that address returns `*fma3`.
struct Lib {
    const Seg* segs;
    int nseg;
    uint64_t fma3Addr;
    const bool* fma3;
};

struct Cpu {
    uint64_t r[16];
    X128 x[16];
    bool cf, zf, sf, of, pf;
    uint32_t mxcsr;  // ldmxcsr/stmxcsr: only the rounding-control bits (13-14) influence results
    const Lib* lib;
    alignas(16) uint8_t stack[kStackSize];
};

[[noreturn]] inline void Trap() { std::fputs("vs2013 lift: trap (fell off decoded code)\n", stderr); std::abort(); }
[[noreturn]] inline void TrapMem(uint64_t a, uint64_t n, bool write) {
    std::fprintf(stderr, "vs2013 lift: %s of %llu bytes at 0x%llx outside the emulated segments\n", write ? "write" : "read",
                 static_cast<unsigned long long>(n), static_cast<unsigned long long>(a));
    std::abort();
}

inline const uint8_t* Ptr(const Cpu& c, uint64_t a, uint64_t n) {
    const uint64_t off = a - kStackBase;
    if (off < kStackSize && off + n <= kStackSize) return c.stack + off;
    for (int i = 0; i < c.lib->nseg; ++i) {
        const Seg& s = c.lib->segs[i];
        if (a >= s.base && a + n <= s.base + s.size) return s.data + (a - s.base);
    }
    TrapMem(a, n, false);
}
inline uint8_t* WPtr(Cpu& c, uint64_t a, uint64_t n) {
    const uint64_t off = a - kStackBase;
    if (off < kStackSize && off + n <= kStackSize) return c.stack + off;
    TrapMem(a, n, true);
}
inline uint64_t Ld(const Cpu& c, uint64_t a, int n) {
    if (a == c.lib->fma3Addr && n == 4) return *c.lib->fma3 ? 1 : 0;
    uint64_t v = 0;
    std::memcpy(&v, Ptr(c, a, static_cast<uint64_t>(n)), static_cast<size_t>(n));
    return v;
}
inline void St(Cpu& c, uint64_t a, uint64_t v, int n) { std::memcpy(WPtr(c, a, static_cast<uint64_t>(n)), &v, static_cast<size_t>(n)); }
inline X128 Ld128(const Cpu& c, uint64_t a) {
    X128 v;
    std::memcpy(&v, Ptr(c, a, 16), 16);
    return v;
}
inline void St128(Cpu& c, uint64_t a, X128 v) { std::memcpy(WPtr(c, a, 16), &v, 16); }

inline double D(uint64_t b) { double d; std::memcpy(&d, &b, 8); return d; }
inline uint64_t B(double d) { uint64_t b; std::memcpy(&b, &d, 8); return b; }
inline float F(uint64_t b) { const uint32_t u = static_cast<uint32_t>(b); float f; std::memcpy(&f, &u, 4); return f; }
inline uint64_t Bf(float f) { uint32_t u; std::memcpy(&u, &f, 4); return u; }
inline uint64_t MergeLo32(uint64_t dst, float f) { return (dst & ~0xffffffffull) | Bf(f); }

constexpr uint64_t Mask(int bits) { return bits == 64 ? ~0ull : ((1ull << bits) - 1); }
inline uint64_t SignBit(int bits) { return 1ull << (bits - 1); }
inline bool Parity(uint64_t v) { return (std::popcount(v & 0xff) & 1) == 0; }

inline uint64_t MulWide(uint64_t a, uint64_t b, uint64_t& hi) {
#ifdef _MSC_VER
    return _umul128(a, b, &hi);
#else
    const unsigned __int128 p = static_cast<unsigned __int128>(a) * b;
    hi = static_cast<uint64_t>(p >> 64);
    return static_cast<uint64_t>(p);
#endif
}
inline int Bsr(uint64_t v) { return 63 - std::countl_zero(v); }

// ---- integer flag helpers (a, b, res are already masked to `bits`) ----
inline void FlLogic(Cpu& c, uint64_t res, int bits) {
    c.cf = false; c.of = false; c.zf = res == 0; c.sf = (res & SignBit(bits)) != 0; c.pf = Parity(res);
}
inline void FlAdd(Cpu& c, uint64_t a, uint64_t b, uint64_t carryIn, uint64_t res, int bits) {
    const uint64_t m = Mask(bits);
    c.cf = bits == 64 ? (res < a || (carryIn && res == a)) : ((a + b + carryIn) > m);
    c.of = ((~(a ^ b) & (a ^ res)) & SignBit(bits)) != 0;
    c.zf = res == 0; c.sf = (res & SignBit(bits)) != 0; c.pf = Parity(res);
}
inline void FlSub(Cpu& c, uint64_t a, uint64_t b, uint64_t res, int bits) {
    c.cf = a < b;
    c.of = (((a ^ b) & (a ^ res)) & SignBit(bits)) != 0;
    c.zf = res == 0; c.sf = (res & SignBit(bits)) != 0; c.pf = Parity(res);
}
inline int64_t SExt(uint64_t v, int bits) {
    if (bits == 64) return static_cast<int64_t>(v);
    const uint64_t s = SignBit(bits);
    return static_cast<int64_t>((v ^ s) - s);
}

// ---- SSE compare flags ----
inline void FlComisd(Cpu& c, double a, double b) {
    c.of = false; c.sf = false;
    if (std::isnan(a) || std::isnan(b)) { c.zf = true; c.pf = true; c.cf = true; }
    else if (a > b) { c.zf = false; c.pf = false; c.cf = false; }
    else if (a < b) { c.zf = false; c.pf = false; c.cf = true; }
    else { c.zf = true; c.pf = false; c.cf = false; }
}

// ---- conversions with x86 semantics (round to nearest even unless truncating; indefinite value on overflow) ----
inline uint64_t Cvttsd2si(double d, int bits) {
    if (bits == 32) {
        if (std::isnan(d) || d >= 2147483648.0 || d <= -2147483649.0) return 0x80000000ull;
        return static_cast<uint32_t>(static_cast<int32_t>(d));
    }
    if (std::isnan(d) || d >= 9223372036854775808.0 || d < -9223372036854775808.0) return 0x8000000000000000ull;
    return static_cast<uint64_t>(static_cast<int64_t>(d));
}
// Round per x86 rounding control (0 nearest-even, 1 down, 2 up, 3 truncate)
inline double RoundMode(double d, int rc) {
    switch (rc & 3) {
        case 0: return std::nearbyint(d);
        case 1: return std::floor(d);
        case 2: return std::ceil(d);
        default: return std::trunc(d);
    }
}
inline uint64_t CvtToInt(double d, int rc, int bits) {  // cvtss2si / cvtsd2si
    const double r = RoundMode(d, rc);
    if (bits == 32) {
        if (std::isnan(r) || r >= 2147483648.0 || r < -2147483648.0) return 0x80000000ull;
        return static_cast<uint32_t>(static_cast<int32_t>(r));
    }
    if (std::isnan(r) || r >= 9223372036854775808.0 || r < -9223372036854775808.0) return 0x8000000000000000ull;
    return static_cast<uint64_t>(static_cast<int64_t>(r));
}
inline uint32_t Cvtsd2dq(double d) {
    const double r = std::nearbyint(d);
    if (std::isnan(r) || r >= 2147483648.0 || r < -2147483648.0) return 0x80000000u;
    return static_cast<uint32_t>(static_cast<int32_t>(r));
}

// ---- stubs for CRT infrastructure that cannot change a result (status word, errno, matherr hook) ----
inline void StubRet0(Cpu& c) { c.r[RAX] = 0; }
inline void StubHandleError(Cpu& c) { c.x[0].lo = c.r[R8]; }  // _handle_error returns its retval argument (no _matherr)
inline void StubErrno(Cpu& c) { c.r[RAX] = kStackBase + kScratchOff; }
inline void StubGetMxcsr(Cpu& c) { c.r[RAX] = 0x1f80; }

}  // namespace ksp::dotnet::vs2013::lift
